${JSON.stringify({title:subplotSelection.subplot.title,premise:subplotSelection.subplot.premise,theme:subplotSelection.subplot.theme,start_state:subplotSelection.subplot.start_state,end_state:subplotSelection.subplot.end_state,turning_points:subplotSelection.subplot.turning_points.map((tp:any,i:number)=>({number:i+1,text:tp.text})),scenes:subplotSelection.subplot.elements.map((e:any)=>({title:e.title,purpose:e.purpose,summary:e.summary}))})}`);
