 async function removeCard(){if(card.type==='style'&&card.subtype==='book')return;const usages=card.type==='style'?await api(`/style/${card.id}/usage`):[];confirm(`Delete “${card.title}”${children.length?` and its ${children.length} children`:''}${usages.length?` (used by ${usages.length} chapters or scenes; they will inherit again)`:''}? Deleted cards cannot be recovered. Chats will remain in the chat archive.`,async()=>{await api(`/cards/${card.id}`,'DELETE');await goto(`/n/${novelId}/${sectionKey}`);notify('Deleted');});}
 async function resolveSuggestion(s:any,accept:boolean,force=false,edits?:string){await safely(async()=>{try{await api(`/suggestions/${s.id}/${accept?'accept':'reject'}`,'POST',accept?{force,...(edits!==undefined?{edits}:{})}:{});await reload();notify(accept?'Suggestion accepted':'Dismissed');}catch(e:any){if(e.status===409&&accept){s.status='stale';suggestions=[...suggestions];notify('This card changed since the suggestion was made');}else throw e;}});}
 async function run(flow:string,text?:string){if(running||suggesting)return;phase='Preparing context…';await safely(async()=>{if(card){await mutations.flush(card.id);if(card.type==='scene')await proseEditor?.flush();const pending=drafts[card.id];if(pending&&Object.keys(pending).length){const patch:any={};for(const [k,v] of Object.entries(pending)){if(k.startsWith('fields.')){patch.fields||={};patch.fields[k.slice(7)]=v;}else patch[k]=v;}await saveCard(patch);if(drafts[card.id]&&Object.keys(drafts[card.id]).length)throw new Error('Save your edits before sending.');}}const result=await api(`/novels/${novelId}/turns`,'POST',{scope,conversationScope:conversationScope||scope,flow,text,includeCardContext,onlyCurrentCard:onlyCurrentCard&&!!card,styleExclusions});styleExclusions=[];sentStyle=[];contextManifest=[];failedTurn='';composer='';running=true;activeTurnScope=`${novelId}/${conversationScope}`;phase='Writing…';streamed='';if(text)messages=[...messages,{role:'user',text}];source?.close();source=new EventSource(`/api/turns/${result.turnId}/stream`);
 const decode=(event:MessageEvent)=>{try{return JSON.parse(event.data);}catch{return event.data;}};
 source.addEventListener('context',(e)=>{const value=decode(e as MessageEvent);contextManifest=Array.isArray(value)?value:value.manifest||[];});
 source.addEventListener('style',(e)=>{sentStyle=decode(e as MessageEvent)||[];});
 source.addEventListener('text',(e)=>{const v=decode(e as MessageEvent);streamed+=typeof v==='string'?v:v.delta||v.text||'';});
 source.addEventListener('phase',(e)=>{const v=decode(e as MessageEvent);const p=typeof v==='string'?v:v.phase;phase=p==='structuring'?'Structuring into cards…':p;});
 source.addEventListener('progress',(e)=>{const v=decode(e as MessageEvent);phase=v.message||`Checking ${v.current||v.completed} of ${v.total} passages…`;});
 source.addEventListener('suggestions',(e)=>{const v=decode(e as MessageEvent);const count=Array.isArray(v)?v.length:(v.suggestions?.length||v.count||0);phase=`${count} suggestions ready for review`;notify(`${count} suggestions in Details`);});
 source.addEventListener('done',(e)=>{const value=decode(e as MessageEvent);source.close();running=false;reload().then(()=>{if(value?.error){failedTurn=result.turnId;error=value.error;notify(error);}});});
 source.addEventListener('error',(e:any)=>{const v=e.data?decode(e):null;source.close();running=false;error=typeof v==='string'?v:v?.message||v?.error||'The connection ended. Try again.';notify(error);void reload();});});}
 async function suggestCards(){if(suggesting||running)return;const requestedNovel=novelId,requestedScope=conversationScope||scope;suggesting=true;await safely(async()=>{const result=await api(`/novels/${requestedNovel}/suggestions/generate`,'POST',{scope:requestedScope,instruction:suggestionInstruction});if(novelId===requestedNovel&&conversationScope===requestedScope){await reload();tab='suggestions';detailsOpen=true;}notify(result.suggestions.length?`${result.suggestions.length} suggestions ready in Details`:'No new card suggestions from this conversation.');});suggesting=false;}
 async function send(){if(composer.trim())await run(sectionKey==='flags'?'ask':card||subplotActive?'card_chat':'capture',composer.trim());}
 async function loadTurnStyle(id:string){if(id in turnStyles)return;await safely(async()=>{const turn=await api(`/turns/${id}`);turnStyles={...turnStyles,[id]:turn.style_context||[]};turnRequests={...turnRequests,[id]:turn.context_manifest?.find((item:any)=>item.request)?.request};});}
 function openSettings(){goto(`/settings?returnTo=${encodeURIComponent($page.url.pathname+$page.url.search)}`);}
 async function linkDialog(){allCards=(await Promise.all(sections.map(s=>api(`/novels/${novelId}/cards?section=${s.key}`)))).flat();let nested=[...allCards.filter(c=>['chapter','setting'].includes(c.type))];while(nested.length){const next=(await Promise.all(nested.map(c=>api(`/cards/${c.id}`)))).flatMap(d=>d.children||[]);allCards.push(...next);nested=next.filter(c=>['scene','setting'].includes(c.type));}linkTarget='';linkLabel='';show('link');}
 async function addLink(){await safely(async()=>{await api('/links','POST',{fromId:linkDirection==='out'?card.id:linkTarget,toId:linkDirection==='out'?linkTarget:card.id,label:linkLabel});dialog.close();await reload();notify('Link added');});}
 async function loadReadMore(){if(readNext==null||loading)return;loading=true;try{const d=await api(`/cards/${cardId}/read?cursor=${encodeURIComponent(readNext)}&offset=${encodeURIComponent(readNext)}`);const appended=[...reader];for(const piece of d.scenes){const last=appended[appended.length-1];if(piece.continued&&last?.sceneId===piece.sceneId)appended[appended.length-1]={...last,prose:last.prose+piece.prose};else appended.push(piece);}reader=appended;readNext=d.next??null;}catch(e:any){error=e.message;}finally{loading=false;}}
 $: if(readerSentinel){observer?.disconnect();observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))loadReadMore();});observer.observe(readerSentinel);}
 async function downloadManuscript(format:string){
  if(exporting)return;exporting=true;
  await safely(async()=>{
   const id=novelId;
   if(card?.type==='scene')await proseEditor?.flush();
   const draft=drafts[card?.id];
   if(card&&draft&&Object.keys(draft).length){
    const patch:any={};for(const [key,value] of Object.entries(draft)){if(key.startsWith('fields.')){patch.fields ||= {};patch.fields[key.slice(7)]=value;}else patch[key]=value;}
    const result=await mutations.save(card.id,patch);drafts={...drafts,[card.id]:clearSavedDrafts(draft,patch)};card=result.card||result;
   }
   const response=await fetch(`/api/novels/${id}/export?format=${format}${format==='pdf'?'&pageSize='+encodeURIComponent(pdfPageSize):''}`);
   if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'Export failed. Try again.');}
   const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');
   const encoded=response.headers.get('content-disposition')?.match(/filename\*=UTF-8''([^;]+)/)?.[1];
   link.href=url;link.download=encoded?decodeURIComponent(encoded):`manuscript.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
   dialog.close();notify('Manuscript exported');
  });exporting=false;
 }
 function theme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('novel-theme',next);}
 async function openLibrary(save=false){await mutations.flush(card.id);const pending=drafts[card.id];if(pending&&Object.keys(pending).length){const patch:any={};for(const [k,v] of Object.entries(pending)){if(k.startsWith('fields.')){patch.fields||={};patch.fields[k.slice(7)]=v;}else patch[k]=v;}await saveCard(patch);if(Object.keys(drafts[card.id]||{}).length)return;}saveLibrarySource=save;show('library');}
 async function refreshStylePreview(){stylePreview=card?await api(`/novels/${novelId}/style/resolve?scope=${card.id}&onlyCurrentCard=${onlyCurrentCard?'1':'0'}`):[];styleExclusions=[];}
 const chips=(c:any):[string,string][]=>c.type==='premise'?[['Expand to a paragraph','expand']]:c.type==='outline'?[['Expand this','expand']]:c.type==='character'?[['Flesh out backstory','flesh'],['Want vs. need','wantneed']]:c.type==='arc'?[['Map the turning points','flesh']]:c.type==='plot'?[['Add complications','flesh']]:[['Flesh out','flesh']];
</script>

<svelte:head><title>{novel?.title?novel.title+' · Reefnote':'Reefnote'}</title></svelte:head>
{#if !novelId}
 <main class="library"><h1>Reefnote</h1><p class="note">A place for your story to take shape.</p><button class="btn" on:click={()=>{title='Untitled novel';premise='';show('novel');}}>Start a new novel</button>{#if error}<p role="alert">{error}</p>{/if}</main>
{:else}
<div class="app" class:workspace class:details-open={detailsOpen} class:nav-collapsed={navCollapsed} class:chat-collapsed={chatCollapsed} data-mob={mobile} style:--chat-width={`${chatWidth}px`}>
 <aside class="rail" aria-label="Story contents"><div class="book"><button class="switch" aria-haspopup="true" aria-expanded={menu} on:click={()=>menu=!menu}><h1>{novel?.title||'Opening…'}</h1><span class="caret">▾</span></button><p>{novel?.tagline||'a novel in progress'}</p>{#if menu}<div class="menu">{#each novels as n}<button class:cur={n.id===novelId} on:click={()=>{menu=false;api(`/novels/${n.id}/open`,'POST');goto(`/n/${n.id}/chapters`);mobile='main';}}>{n.title}<small>{n.id===novelId?'open now':n.tagline}</small></button>{/each}<hr/><button class="add" on:click={()=>{menu=false;title='Untitled novel';premise='';show('novel');}}>+ New novel</button><button class="add" on:click={()=>{menu=false;title=novel.title;premise=novel.tagline;show('editNovel');}}>Edit novel</button></div>{/if}</div>
 <div class="workspace-navigation">
 {#if card||subplotActive}<button class="chip" aria-expanded={bookNavigation} on:click={()=>bookNavigation=!bookNavigation}>Book sections ▾</button>{#if bookNavigation}<nav class="section-menu" aria-label="Book sections">{#each sections as s}<button class="step" on:click={()=>{bookNavigation=false;openSection(s.key);}}>{s.name}</button>{/each}</nav>{/if}<button class="plain back-to-section" on:click={()=>openSection(sectionKey)}>← All {section.name.toLowerCase()}</button>{/if}
 {#if subplotActive}<div class="subplot-navigation-host" bind:this={subplotNavigation}></div>
 {:else if card}<label for="card-switch">{navigatorLabel}</label><select id="card-switch" aria-label={chapter?'Chapter':'Switch card'} value={rootCard?.id||''} on:change={(e)=>openCard(cards.find(c=>c.id===e.currentTarget.value)||{id:e.currentTarget.value,type:rootCard.type})}>{#each cards as c}<option value={c.id}>{c.title}</option>{/each}</select>
 <button class="step" class:on={card.id===rootCard?.id} on:click={()=>openCard(rootCard)}>{chapter?'Chapter overview':'Overview'}</button>
 {#if chapter}<input type="search" aria-label="Filter scenes" placeholder="Find a scene…" bind:value={sceneFilter}/>{/if}
 <nav class="scene-list" aria-label={chapter?'Chapter scenes':'Card contents'}>{#each (chapter?filteredScenes:navigatorItems) as child,i}<div class="scene-nav-row" class:selected={cardId===child.id}><button class="scene-nav" aria-current={cardId===child.id?'page':undefined} on:click={()=>openCard(child)}><span>{i+1}.</span><span>{child.title}</span>{#if child.pendingCount}<span class="count">{child.pendingCount}</span>{/if}</button>{#if chapter}<div class="scene-reorder"><button aria-label={'Move '+child.title+' up'} disabled={i===0} on:click={()=>move(child,-1)}>↑</button><button aria-label={'Move '+child.title+' down'} disabled={i===sceneList.length-1} on:click={()=>move(child,1)}>↓</button></div>{/if}</div>{/each}
 {#if !chapter}{#each [['links','Linked cards'],['history','History'],...(['character','style'].includes(card.type)?[['style','Voice & style']]:[])] as [tool,label]}<button class="step" on:click={()=>{tab=tool;detailsOpen=true;mobile='side';}}>{label}</button>{/each}{/if}</nav>
 {#if chapter}<button class="chip" on:click={()=>createDialog('scene',chapter.id)}>+ Add scene</button><button class="chip" on:click={()=>goto(`/n/${novelId}/chapters/${chapter.id}?read=1`)}>Read chapter</button>{:else if card.type==='setting'}<button class="chip" on:click={()=>createDialog('setting',card.id)}>+ Add location</button>{/if}
 {:else}<nav class="path" aria-label="Book sections"><div class="toc-h">Contents</div>{#each sections as s}{@const count=overview.sections?.find((x:any)=>x.key===s.key)}<button class="step" class:on={sectionKey===s.key} on:click={()=>openSection(s.key)}><span class="txt"><span class="nm">{s.name}</span><span class="lead"></span><span class="pg">{ready?(s.key==='chapters'?`${count?.sceneCount||0} sc`:count?.count||0):''}</span></span>{#if count?.pending}<span class="count">{count.pending}</span>{/if}</button>{/each}</nav>{/if}
 </div><div class="railfoot"><button class="flags" class:has-issues={ready&&overview.flagsPending} on:click={()=>openSection('flags')}><span><b>Continuity check</b><span>{!ready?'Checking…':overview.flagsPending?`${overview.flagsPending} ${overview.flagsPending===1?'issue':'issues'} to review`:'All clear'}</span></span>{#if ready&&overview.flagsPending}<span class="count">{overview.flagsPending}</span>{/if}</button><nav class="rail-links" aria-label="Book tools"><button on:click={openChatArchive}>Chat archive</button><button class="export-manuscript" on:click={()=>show('export')}>Export</button><button on:click={openSettings}>Settings</button><button on:click={theme}>Light / dark</button></nav></div></aside>
 <main class="main"><div class="editor-pane">{#if workspace}<div class="workspace-toolbar"><button class="chip toggle" aria-pressed={!navCollapsed} on:click={()=>navCollapsed=!navCollapsed}>Contents</button><button class="chip toggle" aria-pressed={!chatCollapsed} on:click={()=>chatCollapsed=!chatCollapsed}>Chat</button><span class="tb-sep" aria-hidden="true"></span>{#if subplotActive}<button class="chip" disabled={subplotSelection.busy} on:click={()=>safely(()=>subplotEditor?.showWork()||Promise.resolve())}>Review & history</button>{/if}{#each (card?['suggestions','links','history','style']:['suggestions']) as tool}<button class="chip" on:click={()=>{tab=tool;detailsOpen=true;mobile='side';}}>{tool==='suggestions'?`Suggestions · ${suggestions.length}`:tool[0].toUpperCase()+tool.slice(1)}</button>{/each}</div>{/if}<div class="card-search" role="search"><input type="search" aria-label="Search all cards" placeholder="Search all cards…" bind:value={searchQuery} on:keydown={(e)=>{if(e.key==='Escape')searchQuery='';}}/>{#if searchQuery}<button class="chip" on:click={()=>searchQuery=''}>Clear</button>{/if}</div>{#if ready&&!settings.modelWrite}<div class="banner">Add an AI provider in <button class="plain" on:click={openSettings}>Settings</button> to use the co-writer.</div>{/if}
 {#if subplotActive}<header class="head"><div class="crumbs"><button on:click={()=>openSection('plots')}>← All plots</button>{#if subplotSelection.element}<span>/</span><button on:click={()=>safely(()=>subplotEditor?.openOverview()||Promise.resolve())}>{subplotSelection.subplot?.title}</button>{/if}</div><input class="titlein" aria-label="Card title" title={selectedTitle} value={selectedTitle} disabled={subplotSelection.busy} on:change={(ev)=>{const value=ev.currentTarget.value;void safely(()=>subplotEditor?.rename(value)||Promise.resolve());}}/></header>{:else}<header class="head">{#if card}<div class="crumbs"><button on:click={()=>openSection(sectionKey)}>← All {section.name.toLowerCase()}</button>{#each ancestors as a}<span>/</span><button on:click={()=>openCard(a)}>{a.title}</button>{/each}</div><div class="kindpill">{card.type}{card.subtype?', '+card.subtype:''}</div><input class="titlein" aria-label="Card title" value={fieldValue('title')} on:input={(e)=>editField('title',e.currentTarget.value)} on:blur={(e)=>{if(e.currentTarget.value!==card.title)saveCard({title:e.currentTarget.value});}}/><div class="toolbar"><button class="chip" on:click={()=>{subtype=card.subtype;premise=(card.aliases||[]).join(', ');show('metadata');}}>Type & aliases</button>{#if !(card.type==='style'&&card.subtype==='book')}<button class="chip danger" on:click={()=>safely(removeCard)}>Delete card</button>{/if}</div>{:else}<div class="crumbs">{sectionKey==='flags'?'Continuity':'Your story'}</div><h2>{sectionKey==='flags'?'Story issues':section.name}</h2><div class="sub">{sectionKey==='flags'?'Review loose ends and keep your story consistent.':section.desc}</div>{/if}</header>{/if}
 <div class="scroll" aria-busy={!ready}>{#if error}<p role="alert" class="banner">{error}</p>{/if}{#if !ready&&!error}<p class="empty" role="status">Opening your novel…</p>{:else}
 {#if subplotActive}<SubplotEditor bind:this={subplotEditor} navigationTarget={subplotNavigation} onSelection={onSubplotSelection} onValidateTurningPoints={validateTurningPoints} onDraftScene={draftSceneInChat} chatBusy={running||suggesting}/>{:else}
 {#if review}<section class="review-editor"><h2>Review before applying</h2><p>Replace text in the selected scene. The previous version stays in History.</p><label for="review-destination">Destination scene</label><select id="review-destination" bind:value={reviewDestination} disabled={!!review.suggestion} on:change={()=>safely(destinationPreview)}>{#each sceneList as scene}<option value={scene.id}>{scene.title}</option>{/each}</select><label for="review-field">Field</label><select id="review-field" bind:value={reviewField} disabled={!!review.suggestion} on:change={()=>safely(destinationPreview)}><option value="prose">Prose</option><option value="body">Scene plan</option></select><div class="review-columns"><div><h3>Current text</h3><pre>{reviewBefore||'Empty'}</pre></div><div><h3>Proposed text · editable</h3><textarea aria-label="Proposed scene text" bind:value={reviewText}></textarea></div></div><div class="actions"><button class="btn" disabled={!reviewDestination||reviewLoading} on:click={applyReview}>Accept replacement</button>{#if review.suggestion}<button class="chip" on:click={async()=>{await resolveSuggestion(review.suggestion,false);review=null;}}>Dismiss suggestion</button>{/if}<button class="chip" on:click={()=>review=null}>Cancel</button></div></section>{/if}
 {#if searchQuery.trim()}
 <section aria-label="Search results"><h2>Search results</h2><p class="note" role="status">{searchBusy?'Searching…':searchError?searchError:`${searchResults.length} ${searchResults.length===1?'card':'cards'} found across this novel`}</p><div class="grid">{#each searchResults as result}<button class="card" on:click={()=>{searchQuery='';openCard(result);}}><span class="kind">{result.type}{result.subtype?' · '+result.subtype:''}</span><span class="ttl">{result.title}</span><div class="snip">{result.snippet}</div></button>{/each}</div>{#if !searchBusy&&!searchError&&!searchResults.length}<p>No cards contain “{searchQuery.trim()}”.</p>{/if}</section>
 {:else if card && reading}<div class="actions"><button class="chip" on:click={()=>goto($page.url.pathname)}>← Back to chapter plan</button></div><article class="reading">{#each reader as scene}<section class="reader-scene"><h3>{scene.title}<button on:click={()=>openCard({id:scene.sceneId,type:'scene'})}>Edit</button></h3>{#if scene.prose}{#each scene.prose.split(/\n\s*\n/) as paragraph}<p>{paragraph}</p>{/each}{:else}<p class="gap">Not drafted yet.</p>{/if}</section>{/each}{#if readNext!=null}<div bind:this={readerSentinel}><button class="chip" on:click={loadReadMore}>Load more scenes</button></div>{/if}</article>
 {:else if card}
 {#if workspace&&card.type==='scene'}<div class="editor-tabs" role="tablist" aria-label="Scene editor"><button role="tab" aria-selected={editorTab==='plan'} on:click={()=>editorTab='plan'}>Plan</button><button role="tab" aria-selected={editorTab==='prose'} on:click={()=>editorTab='prose'}>Prose</button></div>{/if}<div hidden={workspace&&card.type==='scene'&&editorTab!=='plan'}>
  {#if card.type==='chapter'}<section class="block"><h3>Chapter plan</h3>{#each [['purpose','Purpose: what this chapter does'],['opens','Opens on: the hook that pulls readers in'],['closes','Closes on: the hook that makes them turn the page']] as [field,label]}<div class="fld"><div class="field-label">{label}</div><MarkdownField id={field} label={label} class="sm" value={fieldValue('fields.'+field)} onInput={(text)=>editField('fields.'+field,text)} onBlur={(text)=>{if(text!==(card.fields?.[field]||''))saveCard({fields:{[field]:text}});}}/></div>{/each}<div class="actions">{#each [['Sharpen the hooks','hooks'],['Brainstorm scenes','scenes'],['Suggest threads','threads']] as [label,flow]}<button class="chip" disabled={running} on:click={()=>run(flow,label)}>{label}</button>{/each}</div></section>
  {:else if card.type==='beat'}<section class="block"><h3>Beat type <HelpTip term="Beat type" text="The kind of story movement this scene provides, such as an action or a reaction. Helps describe its role in the chapter."/></h3><div class="bt">{#each beats as b}<button aria-pressed={card.subtype===b} on:click={()=>saveCard({subtype:b})}>{b}</button>{/each}</div></section>{#if card.subtype==='trap-and-escape'}<section class="block"><h3>Trap and escape <HelpTip term="Trap and escape" text="Plan the pressure or obstacle that closes in on the characters and how they respond or find a way through."/></h3>{#each [['corner','The corner'],['fails','Exits that fail'],['way','The unexpected way out']] as [field,label]}<div class="fld"><div class="field-label">{label}</div><MarkdownField id={field} label={label} class="sm" value={fieldValue('fields.'+field)} onInput={(text)=>editField('fields.'+field,text)} onBlur={(text)=>{if(text!==(card.fields?.[field]||''))saveCard({fields:{[field]:text}});}}/></div>{/each}<div class="actions"><button class="chip" on:click={()=>run('escapes','Brainstorm other escapes')}>Brainstorm other escapes</button><button class="chip" on:click={()=>run('earned','Is the escape earned?')}>Is the escape earned?</button></div></section>{/if}
  {/if}
  {#if card.type==='chapter'}<section class="block"><h3>Chapter notes</h3><p class="note">Planning and reference text for this chapter. Manuscript text belongs in each scene’s Prose field and appears in Read whole chapter.</p><MarkdownField label="Chapter notes" value={fieldValue('body')} onInput={(text)=>editField('body',text)} onBlur={(text)=>{if(text!==card.body)saveCard({body:text});}}/></section>{/if}
  {#if card.type!=='chapter'&&!(card.type==='beat'&&card.subtype==='trap-and-escape')}<section class="block"><h3>{card.type==='scene'?'Scene plan':card.type==='beat'?'What happens':'Notes'}</h3><MarkdownField label={card.type==='scene'?'Scene plan':'Notes'} value={fieldValue('body')} onInput={(text)=>editField('body',text)} onBlur={(text)=>{if(text!==card.body)saveCard({body:text});}}/><div class="actions">{#if card.type==='scene'}<button class="chip" on:click={()=>run('beats','Suggest beats')}>Suggest beats</button><button class="chip" on:click={()=>run('flesh','Strengthen the plan')}>Strengthen the plan</button>{:else if card.type==='beat'}<button class="chip" on:click={()=>run('flesh','Sharpen this beat')}>Sharpen this beat</button>{:else}{#each chips(card) as [label,flow]}<button class="chip" on:click={()=>run(flow,label)}>{label}</button>{/each}{/if}<button class="chip" on:click={()=>run('links','Suggest links')}>Suggest links</button></div></section>{/if}
  {#if card.type==='scene'}<section class="block"><h3>In this scene</h3><div class="who">{#each links.filter(l=>['POV','present','set in','features'].includes(l.label)) as l}<button class="tag" on:click={()=>openCard(l.other)}>{l.other.title}<small>{l.label}</small></button>{/each}</div><div class="actions"><button class="chip" on:click={()=>run('who','Suggest who and where')}>Suggest who and where</button><button class="chip" on:click={linkDialog}>Add a link</button></div></section>{/if}
  {#if ['chapter','scene','plot','secret','theme','question','beat'].includes(card.type)}<section class="block"><h3>{card.type==='beat'?'Setup and payoff':card.type==='scene'?'Threads this scene moves':card.type==='chapter'?'Threads in this chapter':'Where it shows up'}</h3>{#each [...links,...(card.type==='chapter'?descendantThreads:[])].filter(l=>card.type==='beat'?['pays off','uses'].includes(l.label):['opens','advances','resolves','explores'].includes(l.label)) as l}<div class="thr"><button on:click={()=>openCard(l.other)}>{l.other.title}</button><span class="lab {l.label}">{l.direction==='in'&&l.label==='pays off'?'paid off by':l.label}</span>{#if l.inTitle}<small>in {l.inTitle}</small>{/if}</div>{/each}<div class="actions"><button class="chip" on:click={linkDialog}>Add a link</button>{#if ['chapter','scene'].includes(card.type)}<button class="chip" on:click={()=>run('threads','Suggest threads')}>Suggest threads</button>{/if}{#if card.type==='beat'&&card.subtype==='setup'}<button class="chip" on:click={()=>run('payoff','Find a payoff')}>Find a payoff</button>{/if}</div></section>{/if}
  {#if ['chapter','scene','setting'].includes(card.type)&&!(workspace&&card.type==='chapter')}<section class="block"><h3>{card.type==='chapter'?'Scenes':card.type==='scene'?'Beats':'Places within this setting'}</h3>{#each children as child,i}<div class="row"><div class="mv"><button aria-label={'Move '+child.title+' up'} disabled={i===0} on:click={()=>move(child,-1)}>↑</button><button aria-label={'Move '+child.title+' down'} disabled={i===children.length-1} on:click={()=>move(child,1)}>↓</button></div><button class="card" on:click={()=>openCard(child)}><span class="kind">{child.subtype}</span><span class="ttl">{child.title}</span><div class="snip"><Markdown interactive={false} text={child.body||''}/></div>{#if child.pendingCount}<span class="meta"><span class="count">{child.pendingCount}</span></span>{/if}</button></div>{/each}{#if !children.length}<p class="note">No {card.type==='chapter'?'scenes':card.type==='scene'?'beats':'places'} yet. Add one or brainstorm with the co-writer.</p>{/if}<div class="actions"><button class="chip" on:click={()=>createDialog(card.type==='chapter'?'scene':card.type==='scene'?'beat':'setting',card.id)}>+ New {card.type==='chapter'?'scene':card.type==='scene'?'beat':'setting'}</button>{#if card.type==='chapter'}<button class="chip" disabled={running||!children.length} on:click={()=>run('chapter_draft','Draft the complete chapter from its scenes, following their plans, optional beats and linked characters.')}>Draft chapter</button><button class="chip" on:click={()=>goto($page.url.pathname+'?read=1')}>Read whole chapter</button><button class="chip" on:click={()=>run('check','Check chapter continuity')}>Check chapter continuity</button><p class="note">Draft chapter follows scene order, plans, linked characters and any beats. Review and accept each scene’s prose in Details, then Read whole chapter. Accepting replaces that scene’s existing prose; earlier versions remain in History.</p>{/if}</div></section>{/if}
  </div>{#if workspace&&card.type==='chapter'}<div class="actions"><button class="chip" on:click={()=>createDialog('scene',card.id)}>+ Add scene</button><button class="chip" disabled={running||!sceneList.length} on:click={()=>run('chapter_draft','Draft the complete chapter from its scenes.')}>Draft chapter</button><button class="chip" on:click={()=>goto($page.url.pathname+'?read=1')}>Read chapter</button><button class="chip" on:click={()=>run('check','Check chapter continuity')}>Check chapter continuity</button></div>{/if}
  {#if card.type==='scene'}<section class="block" hidden={workspace&&editorTab!=='prose'}><h3>Prose</h3><button class="chip style-summary" on:click={()=>{tab='style';detailsOpen=true;mobile='side';document.getElementById('effective-style')?.setAttribute('open','');}}>{'Style: '+(stylePreview.filter(l=>l.kind!=='dialogue_voice'&&l.kind!=='pov_interior').map(l=>l.kind==='book'?'Book voice':l.kind==='preset'?l.sourceTitle:l.kind.replaceAll('_',' ')).join(' + ')||'No rules')+' · POV: '+(links.find(l=>l.label==='POV'&&l.direction==='out')?.other.title||'None')}</button>{#key card.id+proseGeneration}<ProseEditor bind:this={proseEditor} sceneId={card.id} onSaved={()=>{const id=card.id;api(`/cards/${id}/versions`).then(v=>{if(card?.id===id)versions=v;});api(`/cards/${id}`).then(d=>{if(card?.id===id)card=d.card;});}}/>{/key}<div class="actions">{#each [['Draft this scene','draft'],['Write the dialogue','dialogue'],['Check continuity','check']] as [label,flow]}<button class="chip" on:click={()=>run(flow,label)}>{label}</button>{/each}</div></section>{/if}
 {:else}
  {#if sectionKey==='flags'}<button class="chip" on:click={()=>safely(async()=>{await api(`/novels/${novelId}/checks/run`,'POST');await reload();notify('Checks complete');})}>Run story checks</button>{#if !cards.length}<p class="empty">All clear. Keep writing.</p>{/if}<div class="grid">{#each cards as c}<button class="card" on:click={()=>openCard(c)}><span class="kind">{c.type}</span><span class="ttl">{c.title}</span><div class="snip"><Markdown interactive={false} text={c.body||''}/></div></button>{/each}</div>
  {:else}{#if sectionKey==='plots'}<div class="section-heading"><h3 class="groupname">Plots</h3><button class="chip" on:click={()=>{title='';premise='';show('subplot');}}>+ New plot</button></div><div class="grid">{#each subplotCards as subplot}<button class="card" on:click={()=>safely(()=>openSubplot(subplot.id))}><span class="kind">Plot · {subplot.status.replaceAll('_',' ')}</span><span class="ttl">{subplot.title}</span><div class="snip"><Markdown interactive={false} text={subplot.premise}/></div></button>{/each}</div>{/if}{#if sectionKey==='styles'}<div class="actions"><button class="chip" on:click={()=>run('style_presets','Suggest reusable named presets for this book.')}>Suggest presets</button><button class="chip" on:click={()=>run('recommend_style','Recommend three library book voices based on the premise and outline.')}>Recommend a style</button></div>{/if}{#each section.types.filter(t=>t!=='plot') as t}{#if section.types.length>1}<h3 class="groupname">{names[t]||t}</h3>{/if}<div class="grid">{#each cards.filter(c=>c.type===t) as c}<div class="row" style={t==='chapter'?'':'display:contents'}>{#if t==='chapter'}<div class="mv"><button aria-label={'Move '+c.title+' up'} on:click={()=>move(c,-1)}>↑</button><button aria-label={'Move '+c.title+' down'} on:click={()=>move(c,1)}>↓</button></div>{/if}<button class="card" on:click={()=>openCard(c)}><span class="kind"><span>{c.subtype||'notes'}</span><span>{c.type}</span></span><span class="ttl">{c.title}</span><div class="snip"><Markdown interactive={false} text={(c.type==='chapter'?c.fields?.purpose||c.fields?.opens:c.body)||'A blank card, ready for your ideas.'}/></div><span class="meta">{#if c.childCount}<span>{c.childCount} {c.type==='chapter'?'scenes':'children'}</span>{/if}{#if c.linkCount}<span>{c.linkCount} links</span>{/if}{#if c.pendingCount}<span class="count">{c.pendingCount}</span>{/if}</span></button></div>{/each}<button class="card new" on:click={()=>createDialog(t)}>+ New {t==='chapter'?'chapter':t==='style'?'preset':'card'}</button></div>{/each}{/if}
 {/if}
 {/if}
 {/if}
 </div>
 </div>{#if !reading||workspace}<div class="dock" class:chat-expanded={chatExpanded} class:chat-resized={chatResized} class:resizing={resizingChat} style:height={chatResized?`${chatHeight}%`:undefined}>{#if workspace}<div class="workspace-chat-divider" role="slider" aria-label="Resize chat width" aria-orientation="horizontal" aria-valuemin="300" aria-valuemax="700" aria-valuenow={chatWidth} tabindex="0" on:pointerdown={resizeWorkspaceChat} on:keydown={(e)=>{if(e.key==='ArrowLeft')chatWidth=Math.min(700,chatWidth+30);if(e.key==='ArrowRight')chatWidth=Math.max(300,chatWidth-30);}}></div><div class="workspace-chat-heading"><b>Co-writer</b><span class="head-actions"><button class="chip" aria-pressed={showPins} on:click={()=>showPins=!showPins}>Pinned · {pinned.length}</button><button class="chip" disabled={running||suggesting} on:click={startNewChat}>+ New chat</button></span></div><div class="conversation-heading"><span>{conversationMode==='chapter'&&chapter?chapter.title:selectedTitle} conversation</span>{#if chapter&&card?.type==='scene'}<button class="plain" disabled={running||suggesting} on:click={()=>switchConversation(conversationMode==='chapter'?'scene':'chapter')}>{conversationMode==='chapter'?'Scene chat':'Chapter chat'}</button>{/if}<small>Context: {includeCardContext?(chapter&&chapter.id!==card?.id?`${chapter.title} + ${card?.title}`:selectedTitle):'Conversation only'}</small></div>{#if showPins}<section class="pinned-reference" aria-label="Pinned references"><select aria-label="Pinned response" bind:value={activePin}><option value="">Choose a pinned response</option>{#each pinned as pin}<option value={pin.id}>{pin.text.slice(0,90)}</option>{/each}</select>{#each pinned.filter(p=>p.id===activePin) as pin}<div class="pinned-text"><Markdown text={pin.text}/></div><div class="actions">{#if card?.type==='scene'||sceneList.length}<button class="chip" on:click={()=>reviewResponse(pin)}>Apply to scene…</button>{/if}<button class="plain" on:click={()=>pinResponse(pin)}>Unpin</button></div>{/each}{#if !pinned.length}<p class="note">Pin a response to keep it beside your writing.</p>{/if}</section>{/if}{/if}<div class="chat-divider" role="slider" tabindex="0" aria-label="Resize chat area" aria-orientation="vertical" aria-valuemin="20" aria-valuemax="70" aria-valuenow={chatHeight} on:pointerdown={resizeChat} on:keydown={resizeChatKey}></div><div class="chat-mobile-toolbar"><span>Co-writer</span><button class="chip" aria-expanded={chatExpanded} on:click={()=>chatExpanded=!chatExpanded}>{chatExpanded?'Back to writing':'Expand chat'}</button></div><div class="thread" bind:this={chatThread} on:scroll={()=>{if(conversationScope&&chatThread)chatPositions[conversationScope]=chatThread.scrollTop;}}>{#each messages as m}<div class="msg" class:me={m.role==='user'} class:ai={m.role==='assistant'}>{#if m.role==='assistant'}<Markdown text={m.text}/>{#if workspace&&m.id}<div class="actions"><button class="chip" aria-pressed={pinned.some(p=>p.id===m.id)} on:click={()=>pinResponse(m)}>{pinned.some(p=>p.id===m.id)?'Unpin':'Pin response'}</button>{#if card?.type==='scene'||sceneList.length}<button class="chip" on:click={()=>reviewResponse(m)}>Apply to scene…</button>{/if}{#if subplotActive&&subplotSelection.element}<button class="chip" disabled={running||suggesting} on:click={()=>prepareSceneDraft(m)}>Prepare scene draft</button>{/if}</div>{/if}{#if m.turn_id}{#if subplotActive&&subplotSelection.element}<details class="context-used" on:toggle={(e)=>{if(e.currentTarget.open)void loadTurnStyle(m.turn_id);}}><summary>Context sent to AI <HelpTip term="Context sent to AI" text="Inspect the saved request to see which story information and instructions the AI received for this response."/></summary>{#if turnRequests[m.turn_id]}<SceneRequestContext request={turnRequests[m.turn_id]}/>{:else}<p class="note">No full request snapshot was recorded for this older response.</p>{/if}</details>{/if}<details class="message-style" on:toggle={(e)=>{if(e.currentTarget.open)void loadTurnStyle(m.turn_id);}}><summary>Style used for this response</summary>{#if turnStyles[m.turn_id]}{#each turnStyles[m.turn_id] as layer}<details><summary>{layer.kind.replaceAll('_',' ')} · {layer.sourceTitle} · revision {layer.sourceRev}{layer.truncated?' · Samples shortened':''}</summary><Markdown text={layer.text}/></details>{:else}<p class="note">No style layers were recorded for this response.</p>{/each}{:else}<p class="note">Loading…</p>{/if}</details>{/if}{:else}{m.text}{/if}</div>{/each}{#if running}<div class="msg ai"><Markdown text={streamed}/><div class="pass" aria-live="polite">{phase}</div></div>{/if}{#each sceneDraftCards as p}<article class="sug scene-draft-card"><strong>Scene draft · {subplotSelection.element?.title}</strong><p class="note">Review or edit this complete draft. Accepting replaces this scene’s prose.</p><textarea aria-label="Final scene draft" rows="14" value={draftCardEdits[p.id]??p.payload.text} on:input={(e)=>draftCardEdits={...draftCardEdits,[p.id]:e.currentTarget.value}}></textarea><div class="actions"><button class="btn" disabled={running||suggesting||!(draftCardEdits[p.id]??p.payload.text).trim()} on:click={()=>resolveSceneDraft(p,true)}>Accept into scene prose</button><button class="chip" disabled={running||suggesting} on:click={()=>resolveSceneDraft(p,false)}>Dismiss</button></div></article>{/each}</div>{#if failedTurn}<div class="hint"><button class="chip" on:click={()=>safely(async()=>{await api(`/turns/${failedTurn}/retry-structure`,'POST');failedTurn='';await reload();notify('Suggestions ready for review');})}>Retry turning response into cards</button></div>{/if}{#if contextManifest.length}<details class="context-used" open={running}><summary>Context used · {contextManifest.filter(item=>!item.request).length} cards</summary>{#each contextManifest as item}{#if item.request}<details open={running}><summary>Context sent to AI · {item.request.model}</summary><SceneRequestContext request={item.request}/></details>{:else}<div>{(item.type||'Card').replaceAll('_',' ').replace(/^./, (letter:string)=>letter.toUpperCase())} · {item.title||'Deleted card'} · {item.form} · {item.tokens} tokens</div>{/if}{/each}</details>{/if}{#if sentStyle.length}<details class="style-used"><summary>Style used · {sentStyle.length} layers</summary>{#each sentStyle as layer}<details><summary>{layer.kind.replaceAll('_',' ')} · {layer.sourceTitle} · revision {layer.sourceRev}{layer.truncated?' · Samples shortened':''}</summary><button class="plain" on:click={()=>openCard({id:layer.sourceCardId,type:layer.kind==='dialogue_voice'||layer.kind==='pov_interior'?'character':layer.kind==='chapter_notes'?'chapter':layer.kind==='scene_notes'?'scene':'style'})}>Open source</button><Markdown text={layer.text}/></details>{/each}</details>{/if}{#if !messages.length}<div class="hint"><button class="chip" disabled={running} on:click={()=>run('brainstorm',`Brainstorm ${card?card.title:section.name.toLowerCase()}`)}>Brainstorm {card?'ideas':'some '+section.name.toLowerCase()}</button><button class="chip" on:click={()=>{composer='What might be missing from this part of the story?';}}>What might be missing?</button></div>{/if}<div class="card-suggestion-controls"><div class="card-suggestion-heading"><button class="chip" disabled={running||suggesting||!messages.length} on:click={suggestCards}>{suggesting?'Suggesting cards…':'Suggest cards'}</button><span>From this whole chat · latest decisions</span></div><details class="card-suggestion-options"><summary>Add instructions (optional)</summary><textarea aria-label="Card suggestion instructions (optional)" placeholder="For example: Extract only characters as cards" rows="2" bind:value={suggestionInstruction} disabled={suggesting}></textarea></details></div><details class="chat-context-options"><summary>Chat context <HelpTip term="Chat context" text="Story information supplied alongside your message. Its scope depends on the selected plot, scene, or card. Review Context sent to AI where available to see the actual request."/></summary><div class="chat-context"><label><input type="checkbox" bind:checked={includeCardContext} disabled={running}/> Send card context <HelpTip term="Send card context" text="Include story information from the selected plot, scene, or card when asking the AI. Turn this off to send conversation context only."/></label><label><input type="checkbox" bind:checked={onlyCurrentCard} on:change={()=>safely(refreshStylePreview)} disabled={running||!includeCardContext||!card}/> Send only current card <HelpTip term="Send only current card" text="Restrict card context to the selected card instead of including related cards and wider story context. Available when a card is selected."/></label><span>{includeCardContext&&onlyCurrentCard&&card?'Only this card informs chat responses.':includeCardContext?'Cards inform chat responses.':'Conversation only.'}</span></div>{#if includeCardContext&&stylePreview.length}<div class="style-context"><h4>Style · next send</h4>{#each stylePreview as layer}<details><summary><label><input type="checkbox" checked={!styleExclusions.includes(layer.id)} disabled={running} on:change={(e)=>{styleExclusions=e.currentTarget.checked?styleExclusions.filter(id=>id!==layer.id):[...styleExclusions,layer.id];}}/>{layer.kind.replaceAll('_',' ')} · {layer.sourceTitle}</label></summary><Markdown text={layer.text}/></details>{/each}<p class="note">Unchecked layers are excluded for one send.</p></div>{/if}</details><div class="composer"><textarea aria-label="Message to co-writer" placeholder={sectionKey==='flags'?'Ask about your story…':`Brainstorm ${card?card.title:section.name.toLowerCase()}…`} bind:value={composer} on:keydown={(e)=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}}}></textarea>{#if running}<button class="btn ghost" on:click={stopTurn}>Stop</button>{/if}<button class="btn" disabled={running||suggesting||!composer.trim()} on:click={send}>{running?'Writing…':'Send'}</button></div></div>{/if}</main>
 <aside class="side" aria-label="Details">{#if workspace}<button class="chip drawer-close" on:click={()=>{detailsOpen=false;mobile='main';}}>Close details</button>{/if}<div class="scope">{card?'Selected card':'Showing everything in'}<b>{card?.title|| (sectionKey==='flags'?'Story issues':section.name)}</b></div><div class="dtabs" role="tablist" aria-label="Card details">{#each card?(workspace?['suggestions','links','history','style']:['suggestions','links','history']):['suggestions'] as t}<button role="tab" aria-selected={tab===t} on:click={()=>tab=t}>{t[0].toUpperCase()+t.slice(1)}{t==='suggestions'&&suggestions.length?' · '+suggestions.length:''}</button>{/each}</div><div class="dbody">{#if card&&(!workspace||tab==='style')&&['style','chapter','scene','character'].includes(card.type)}<StyleControls {card} onChanged={reload} onLibrary={openLibrary} onRun={run} onOpen={openCard}/>{/if}
 {#if card&&['character','group','setting','object','secret'].includes(card.type)}<CardAppearances {card}/>{/if}
 {#if tab==='suggestions'||!card}{#if !suggestions.length}<p class="note">No suggestions waiting. Use Suggest cards in chat when your ideas are ready.</p>{/if}{#each suggestions as s}<article class="sug"><span class="suggestion-operation">{suggestionOperation(s)}</span><time class="suggestion-time" datetime={new Date(s.created_at).toISOString()} title={new Date(s.created_at).toLocaleString()}>{new Date(s.created_at).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</time><div class="suggestion-target"><span class="suggestion-type">{s.action==='create_card'?s.payload?.type:s.target_type||'Unavailable card'}</span><strong>{s.action==='create_card'?s.payload?.title:s.target_title||'Card no longer available'}</strong></div><div class="what"><Markdown text={s.what||''}/></div><div class="why"><span class="suggestion-reason-label">Reason</span><Markdown text={s.why||'No reason was provided for this suggestion.'}/></div>{#if s.preview}<div class="preview"><Markdown text={s.preview}/></div>{/if}{#if s.status==='stale'}<p class="help">This card changed since the suggestion was made.</p>{/if}<div class="acts"><button class="btn sm ok" on:click={()=>workspace&&suggestionChange(s)?.field==='prose'?reviewProseSuggestion(s):resolveSuggestion(s,true,s.status==='stale')}>{workspace&&suggestionChange(s)?.field==='prose'?'Review in editor':s.status==='stale'?'Apply anyway':s.action==='flag_issue'?(s.payload?.fix?'Apply fix':'Mark reviewed'):'Accept'}</button><button class="btn sm ghost" on:click={()=>resolveSuggestion(s,false)}>{s.action==='flag_issue'?"It's intentional":'Dismiss'}</button>{#if ['create_card','update_card'].includes(s.action)}<button class="btn sm ghost" on:click={()=>{editSuggestion=s;editText=s.payload?.text||s.payload?.body||s.preview;show('suggestion');}}>Edit</button>{/if}</div></article>{/each}
 {:else if tab==='links'}<button class="chip" on:click={linkDialog}>+ Add link</button>{#if !links.length}<p class="note">No links yet. Connect this card to your story.</p>{/if}{#each links as l}<div class="ver"><button class="lnk" on:click={()=>openCard(l.other)}><span>{l.other.title}<small>{l.direction==='in'?'←':'→'} {l.label||'linked'}</small></span></button><button class="plain danger" aria-label={'Remove link to '+l.other.title} on:click={()=>safely(async()=>{await api(`/links/${l.id}`,'DELETE');await reload();})}>×</button></div>{/each}
 {:else if tab==='history'}<p class="note">Every change has a past. Restore a version to bring it back.</p>{#each versions as v}<div class="ver"><div>{v.note}<span>{new Date(v.created_at).toLocaleString()} · {v.source}</span></div><button class="btn sm ghost" on:click={()=>confirm('Restore this version? Your current text will be saved in history.',async()=>{await api(`/versions/${v.id}/restore`,'POST');await reload();proseGeneration++;notify('Version restored');})}>Restore</button></div>{/each}{/if}</div></aside>
 <nav class="mob" aria-label="Mobile navigation">{#each (workspace?[['rail','Story'],['main','Editor'],['chat','Chat'],['side','Details']]:[['rail','Story'],['main','Write'],['side','Details']]) as [key,label]}<button aria-pressed={mobile===key} on:click={()=>{mobile=key;if(key==='side')detailsOpen=true;}}>{label}{key==='side'&&suggestions.length?' · '+suggestions.length:''}</button>{/each}</nav>
</div>
{/if}
<dialog class:style-library-dialog={dialogKind==='library'} bind:this={dialog} on:close={()=>dialogKind=''}><div class="dlg">
{#if dialogKind==='subplot'}<h2>New plot</h2><label for="subplot-title">Title</label><input id="subplot-title" bind:value={title}/><label for="subplot-premise">Premise</label><textarea id="subplot-premise" bind:value={premise}></textarea><div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" disabled={!title.trim()} on:click={()=>safely(async()=>{const p=await api(`/novels/${novelId}/subplots`,'POST',{title,premise});dialog.close();await openSubplot(p.id);})}>Create plot</button></div>
{:else if dialogKind==='novel'||dialogKind==='card'}<h2>{dialogKind==='novel'?'Start a new novel':'A blank card'}</h2><p class="lead">Start wherever your story starts.</p><label for="newtitle">{dialogKind==='novel'?'Working title':'Title'}</label><input id="newtitle" bind:value={title}/>{#if dialogKind==='novel'}<label for="premise">Premise in a sentence (optional)</label><textarea id="premise" bind:value={premise}></textarea>{:else}{#if !parentId}<label for="cardtype">Card type</label><select id="cardtype" bind:value={type}>{#each section.types.filter(t=>t!=='plot') as t}<option value={t}>{t}</option>{/each}</select>{/if}<label for="subtype">Subtype (optional)</label><input id="subtype" bind:value={subtype}/>{/if}<div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" on:click={create}>{dialogKind==='novel'?'Create novel':'Create card'}</button></div>
{:else if dialogKind==='library'}<StyleLibrary {card} saveSource={saveLibrarySource} onApplied={async()=>{dialog.close();await reload();notify('Style applied');}} onMerge={async(text)=>{dialog.close();await run('style_merge','Merge the following library style into this card, preserving unrelated content. Return the complete proposed body for approval.\n\n'+text);}}/><div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Close</button></div>
{:else if dialogKind==='export'}<h2>Export manuscript</h2><p class="help">Download all chapters and scene prose in story order, with breaks between scenes. Story notes and suggestions stay in Reefnote.</p><label for="pdf-page-size">PDF page size</label><select id="pdf-page-size" bind:value={pdfPageSize} disabled={exporting}>{#each PDF_SIZES as size}<option value={size.id}>{size.label}</option>{/each}</select><p class="help">Applies to PDF exports only.</p><div class="actions"><button class="btn" disabled={exporting} on:click={()=>downloadManuscript('epub')}>EPUB</button><button class="btn" disabled={exporting} on:click={()=>downloadManuscript('pdf')}>PDF</button><button class="btn" disabled={exporting} on:click={()=>downloadManuscript('md')}>Markdown (.md)</button></div>{#if exporting}<p class="help" role="status">Preparing your manuscript…</p>{/if}<div class="foot"><button class="btn ghost" disabled={exporting} on:click={()=>dialog.close()}>Close</button></div>
{:else if dialogKind==='confirm'}<h2>Confirm</h2><p>{confirmText}</p><div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" on:click={()=>safely(async()=>{await confirmAction();dialog.close();})}>Confirm</button></div>
{:else if dialogKind==='link'}<h2>Add a link</h2><label for="linktarget">Connect to</label><select id="linktarget" bind:value={linkTarget}><option value="">Choose a card</option><CardLinkOptions cards={allCards.filter(c=>c.id!==card?.id)}/></select><label for="linklabel">Label</label><input id="linklabel" bind:value={linkLabel} list="labels" placeholder="e.g. POV, advances, pays off"/><datalist id="labels">{#each ['POV','present','set in','features','opens','advances','resolves','explores','pays off','uses','arc of','between'] as l}<option value={l}></option>{/each}</datalist><label for="direction">Direction</label><select id="direction" bind:value={linkDirection}><option value="out">This card → chosen card</option><option value="in">Chosen card → this card</option></select><div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" disabled={!linkTarget} on:click={addLink}>Add link</button></div>
{:else if dialogKind==='metadata'}<h2>Type & aliases</h2><label for="meta-subtype">Subtype</label><input id="meta-subtype" disabled={card.type==='style'} bind:value={subtype} list={card.type==='beat'?'beat-types':undefined}/><datalist id="beat-types">{#each beats as b}<option value={b}></option>{/each}</datalist><label for="aliases">Aliases (comma separated)</label><input id="aliases" bind:value={premise}/><div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" on:click={async()=>{await saveCard({subtype,aliases:premise.split(',').map(x=>x.trim()).filter(Boolean)});dialog.close();}}>Save</button></div>
{:else if dialogKind==='suggestion'}<h2>Edit suggestion</h2><p class="lead">Make it yours before accepting.</p><MarkdownField label="Suggestion text" style="min-height:240px" bind:value={editText}/><div class="foot"><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" on:click={async()=>{await resolveSuggestion(editSuggestion,true,false,editText);dialog.close();}}>Accept edited text</button></div>
{:else if dialogKind==='editNovel'}<h2>Edit novel</h2><label for="noveltitle">Working title</label><input id="noveltitle" bind:value={title}/><label for="tagline">Tagline</label><input id="tagline" bind:value={premise}/><div class="foot"><button class="btn ghost danger" on:click={()=>{dialog.close();confirm('Delete this novel and every card? This cannot be undone.',async()=>{await api(`/novels/${novelId}`,'DELETE');await goto('/');});}}>Delete novel</button><button class="btn ghost" on:click={()=>dialog.close()}>Cancel</button><button class="btn" on:click={()=>safely(async()=>{await api(`/novels/${novelId}`,'PATCH',{title,tagline:premise});dialog.close();await reload();})}>Save</button></div>
{/if}{#if error}<p role="alert" class="help danger">{error}</p>{/if}</div></dialog>
{#if toast}<div class="toast on" role="status">{toast}</div>{/if}
